exercises.starter:
function average3(a, b, c) {
  // return the mean of a, b, c rounded to the nearest integer
}

exercises.solution:
function average3(a, b, c) {
  return Math.round((a + b + c) / 3)
}

exercises.starter:
function hypotenuse(a, b) {
  // return sqrt(a^2 + b^2) rounded to the nearest integer
}

exercises.solution:
function hypotenuse(a, b) {
  return Math.round(Math.sqrt(a ** 2 + b ** 2))
}

