  // return true when n is even
}

function wholeDivide(a, b) {
  // return the whole-number part of a / b
}

exercises.solution:
function wholeDivide(a, b) {
  return Math.floor(a / b)
}

exercises.starter:
function absoluteDifference(a, b) {
  // return the non-negative distance between a and b
}

exercises.solution:
function absoluteDifference(a, b) {
  return Math.abs(a - b)
}

exercises.starter:
function clampToRange(x, lo, hi) {
  // bound x to lo..hi using Math.min and Math.max
}

exercises.solution:
function clampToRange(x, lo, hi) {
  return Math.max(lo, Math.min(x, hi))
}
